class Rectangle {
  constructor(height, width) {
    this.height = height;
    this.width = width;
  }
  showName() {
    console.log('Rectangle');
  }
  async load() {
    return 1;
  }
  *iter() {
    yield this.height;
  }
}

class Rectangle {
  get area() {
    return this.calcArea();
  }
  calcArea() {
    return this.height * this.width;
  }
}
